from itertools import permutations

def check_all_constraints(people, colors, pets, drinks, hobbies):
    def idx(item, collection):
        return collection.index(item)

    # Constraint 1: Green house immediately left of Casey
    casey_idx = idx('Casey', people)
    green_idx = idx('green', colors)
    if green_idx != casey_idx - 1:
        return False

    # Constraint 2: Milk drinker lives next to red house
    milk_idx = idx('milk', drinks)
    red_idx = idx('red', colors)
    if abs(milk_idx - red_idx) != 1:
        return False

    # Constraint 3: Parker does hiking
    parker_idx = idx('Parker', people)
    if idx('hiking', hobbies) != parker_idx:
        return False

    # Constraint 4: Taylor does baking
    taylor_idx = idx('Taylor', people)
    if idx('baking', hobbies) != taylor_idx:
        return False

    # Constraint 5: Casey immediately left of juice drinker
    juice_idx = idx('juice', drinks)
    if juice_idx != casey_idx + 1:
        return False

    # Constraint 6: Quinn in green house
    quinn_idx = idx('Quinn', people)
    if green_idx != quinn_idx:
        return False

    # Constraint 7: Water drinker lives next to Blake
    blake_idx = idx('Blake', people)
    water_idx = idx('water', drinks)
    if abs(water_idx - blake_idx) != 1:
        return False

    # Constraint 8: Parker owns rabbit
    if idx('rabbit', pets) != parker_idx:
        return False

    # Constraint 9: Fish owner doesn't drink coffee
    fish_idx = idx('fish', pets)
    coffee_idx = idx('coffee', drinks)
    if fish_idx == coffee_idx:
        return False

    # Constraint 10: Coffee drinker does painting
    if idx('painting', hobbies) != coffee_idx:
        return False

    # Constraint 11: Rower is in blue house
    blue_idx = idx('blue', colors)
    if idx('rowing', hobbies) != blue_idx:
        return False

    # Constraint 12: Taylor lives next to red house
    if abs(taylor_idx - red_idx) != 1:
        return False

    # Constraint 13: Orange house person does painting
    orange_idx = idx('orange', colors)
    if idx('painting', hobbies) != orange_idx:
        return False

    # Constraint 14: Juice drinker is not Taylor
    if juice_idx == taylor_idx:
        return False

    # Constraint 15: Horse owner lives next to Casey
    horse_idx = idx('horse', pets)
    if abs(horse_idx - casey_idx) != 1:
        return False

    # Constraint 16: Quinn owns bird
    if idx('bird', pets) != quinn_idx:
        return False

    return True

people = ['Blake', 'Casey', 'Parker', 'Quinn', 'Taylor']
colors = ['blue', 'green', 'orange', 'red', 'white']
pets = ['bird', 'cat', 'fish', 'horse', 'rabbit']
drinks = ['coffee', 'juice', 'milk', 'tea', 'water']
hobbies = ['baking', 'fencing', 'hiking', 'painting', 'rowing']

solutions = []

for people_perm in permutations(people):
    for colors_perm in permutations(colors):
        for pets_perm in permutations(pets):
            for drinks_perm in permutations(drinks):
                for hobbies_perm in permutations(hobbies):
                    if check_all_constraints(people_perm, colors_perm, pets_perm, drinks_perm, hobbies_perm):
                        solutions.append((people_perm, colors_perm, pets_perm, drinks_perm, hobbies_perm))

if solutions:
    cat_idx = solutions[0][2].index('cat')
    cat_owner = solutions[0][0][cat_idx]
    print(f"ANSWER: {cat_owner}")
else:
    print("ANSWER: UNKNOWN")
